package cn.shiguang.qwenpocket;
import org.json.*;import java.nio.file.*;import java.io.*;import java.util.*;import java.util.zip.*;
public final class ToolsCoreTest {
 static int checks=0;static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);checks++;}
 static void rejects(Runnable run){try{run.run();throw new AssertionError("Expected rejection");}catch(IllegalArgumentException|ArithmeticException expected){checks++;}}
 public static void main(String[] args)throws Exception{
  check(ExactMath.calculate("0.1 + 0.2").equals("0.3"),"decimal addition");check(ExactMath.calculate("(12.50+8.30)×2").equals("41.6"),"receipt");check(ExactMath.calculate("-2^2").equals("-4"),"unary precedence");check(ExactMath.calculate("2^3^2").equals("512"),"power associativity");check(ExactMath.calculate("2^-3").equals("0.125"),"negative exponent");rejects(()->ExactMath.calculate("1/0"));rejects(()->ExactMath.calculate("2^(-2147483648)"));rejects(()->ExactMath.calculate("2+run()"));rejects(()->ExactMath.calculate("(".repeat(80)+"1"+")".repeat(80)));
  JSONArray library=new JSONArray().put(new JSONObject().put("name","食堂账单").put("text","食堂午餐价格为12.50元，晚餐价格为8.30元。").put("enabled",true)).put(new JSONObject().put("name","禁止检索").put("text","食堂午餐价格为999元。").put("enabled",false));String refs=LocalLibrary.retrieve(library,"食堂午餐价格是多少");check(refs.contains("12.50")&&refs.contains("[资料1]")&&!refs.contains("999"),"grounded enabled retrieval");check(LocalLibrary.retrieve(library,"正方体折叠").isEmpty(),"no unrelated source");
  boolean[] cross=new boolean[25];for(int i:new int[]{2,6,7,8,12,17})cross[i]=true;check(CubeNet.describe(cross).contains("↔"),"valid cube cross");boolean[] rectangle=new boolean[25];for(int i:new int[]{0,1,2,5,6,7})rectangle[i]=true;rejects(()->CubeNet.fold(rectangle));boolean[] isolated=cross.clone();isolated[17]=false;isolated[24]=true;rejects(()->CubeNet.fold(isolated));
  // Enumerate all free hexominoes and verify exactly eleven cube nets.
  Set<String> shapes=new HashSet<>();shapes.add("0,0;");for(int n=1;n<6;n++){Set<String> next=new HashSet<>();for(String shape:shapes){List<int[]> cells=parse(shape);for(int[] c:cells)for(int[] step:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int x=c[0]+step[0],y=c[1]+step[1];boolean occupied=false;for(int[] q:cells)occupied|=q[0]==x&&q[1]==y;if(occupied)continue;ArrayList<int[]> expanded=new ArrayList<>(cells);expanded.add(new int[]{x,y});next.add(canonical(expanded));}}shapes=next;}check(shapes.size()==35,"35 free hexominoes");int valid=0;for(String shape:shapes){boolean[] grid=new boolean[25];boolean fits=true;for(int[] c:parse(shape)){if(c[0]>=5||c[1]>=5){fits=false;break;}grid[c[1]*5+c[0]]=true;}if(fits)try{CubeNet.fold(grid);valid++;}catch(IllegalArgumentException ignored){}}check(valid==11,"eleven cube nets");
  Path root=Files.createTempDirectory(Paths.get("build"),"archive-test-");File images=root.resolve("images").toFile();images.mkdirs();Path original=images.toPath().resolve("abc.jpg");Files.write(original,new byte[]{1,2,3});JSONObject user=new JSONObject().put("role","user").put("text","图片账单").put("image",original.toAbsolutePath().toString());JSONObject session=new JSONObject().put("id","same-id").put("draftImage",original.toAbsolutePath().toString()).put("messages",new JSONArray().put(user));JSONObject data=new JSONObject().put("sessions",new JSONArray().put(session));ByteArrayOutputStream out=new ByteArrayOutputStream();AppArchive.write(out,data,library,images);check(user.getString("image").equals(original.toAbsolutePath().toString()),"export does not mutate history");AppArchive.Restored restored=AppArchive.read(new ByteArrayInputStream(out.toByteArray()),root.resolve("read").toFile());check(restored.data.getJSONArray("sessions").getJSONObject(0).getString("draftImage").equals("images/abc.jpg"),"portable paths");check(restored.library.length()==2,"library round trip");check(Files.exists(root.resolve("read/images/abc.jpg")),"image restored");
  for(String attack:new String[]{"../escape","/absolute","images/../bad.jpg","api-key.txt"}){ByteArrayOutputStream bad=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(bad)){AppArchive.put(z,attack,new byte[]{1});}try{AppArchive.read(new ByteArrayInputStream(bad.toByteArray()),root.resolve(UUID.randomUUID().toString()).toFile());throw new AssertionError("accepted "+attack);}catch(IOException expected){checks++;}}
  check(TaskCatalog.NAMES.length==TaskCatalog.GUIDE.length&&TaskCatalog.GROUP.length==TaskCatalog.NAMES.length,"task schema");check(TaskCatalog.safe(300)==0,"unknown task migration");
  JSONObject result=new JSONObject().put("checks",checks).put("cube_nets_valid",valid).put("hexominoes_checked",35).put("phone_test",false);Files.writeString(Paths.get("build/tools-core-validation.json"),result.toString(2));System.out.println(result);
 }
 static List<int[]> parse(String shape){List<int[]> out=new ArrayList<>();for(String c:shape.split(";")){String[] p=c.split(",");out.add(new int[]{Integer.parseInt(p[0]),Integer.parseInt(p[1])});}return out;}
 static String canonical(List<int[]> points){String best=null;for(int flip:new int[]{-1,1})for(int rotation=0;rotation<4;rotation++){List<int[]> transformed=new ArrayList<>();int minX=999,minY=999;for(int[] p:points){int x=p[0]*flip,y=p[1];for(int r=0;r<rotation;r++){int temp=x;x=-y;y=temp;}transformed.add(new int[]{x,y});minX=Math.min(minX,x);minY=Math.min(minY,y);}for(int[] p:transformed){p[0]-=minX;p[1]-=minY;}transformed.sort((a,b)->a[0]!=b[0]?a[0]-b[0]:a[1]-b[1]);StringBuilder s=new StringBuilder();for(int[] p:transformed)s.append(p[0]).append(',').append(p[1]).append(';');String value=s.toString();if(best==null||value.compareTo(best)<0)best=value;}return best;}
}
